"""Patch the Android project generated by `flutter create` in CI.

- INTERNET + CAMERA permissions, app label
- minSdk >= 23 (flutter_secure_storage)
- release signing from env (KEYSTORE_BASE64, KEYSTORE_PASSWORD, KEY_ALIAS, KEY_PASSWORD)
"""
import base64
import os
import pathlib
import re
import sys

APP_LABEL = "SSH Servers"
app = pathlib.Path("android/app")

manifest = app / "src/main/AndroidManifest.xml"
m = manifest.read_text(encoding="utf-8")
for perm in ("INTERNET", "CAMERA"):
    if f"android.permission.{perm}" not in m:
        m = m.replace("<application", f'<uses-permission android:name="android.permission.{perm}"/>\n    <application', 1)
m = re.sub(r'android:label="[^"]*"', f'android:label="{APP_LABEL}"', m, count=1)
manifest.write_text(m, encoding="utf-8")
print("Patched AndroidManifest.xml")

keystore = os.environ.get("KEYSTORE_BASE64", "").strip()
if keystore:
    (app / "upload.p12").write_bytes(base64.b64decode(keystore))

kts = app / "build.gradle.kts"
if not kts.exists():
    sys.exit("android/app/build.gradle.kts not found")
g = kts.read_text(encoding="utf-8")
g = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = maxOf(flutter.minSdkVersion, 23)", g)
if keystore:
    block = """signingConfigs {
        create("release") {
            storeFile = file("upload.p12")
            storeType = "pkcs12"
            storePassword = System.getenv("KEYSTORE_PASSWORD")
            keyAlias = System.getenv("KEY_ALIAS")
            keyPassword = System.getenv("KEY_PASSWORD")?.takeIf { it.isNotEmpty() }
                ?: System.getenv("KEYSTORE_PASSWORD")
        }
    }

    buildTypes {"""
    g = re.sub(r"buildTypes\s*\{", block, g, count=1)
    g = g.replace('signingConfigs.getByName("debug")', 'signingConfigs.getByName("release")')
kts.write_text(g, encoding="utf-8")
print("Patched build.gradle.kts" + (" (release signing)" if keystore else ""))
